article_about_en = make_article(ABOUT, 'en', 'about')

# A count gate keeps the explicit 4,000-word requirement from silently regressing.
for name, value in [('home_vi', article_home_vi), ('home_en', article_home_en), ('about_vi', article_about_vi), ('about_en', article_about_en)]:
    print(name, word_count(value))
    if word_count(value) < 4000:
        raise SystemExit(f'{name} below 4,000 words; revise topic content before generating the migration')

